package EdifiQ.controller;
import EdifiQ.dto.VigilanteRequest; import EdifiQ.service.VigilanteService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/api/vigilantes") @PreAuthorize("hasRole('ADMINISTRADOR')") public class VigilanteController { private final VigilanteService s; public VigilanteController(VigilanteService s){this.s=s;} @GetMapping public List<Map<String,Object>> list(@RequestParam(defaultValue="") String q,@RequestParam(required=false) Integer estado){return s.buscar(q,estado);} @PostMapping public Map<String,String> save(@Valid @RequestBody VigilanteRequest r){s.guardar(r);return Map.of("message","Vigilante guardado correctamente");} @PatchMapping("/{id}/estado") public void toggle(@PathVariable Integer id){s.toggle(id);} @DeleteMapping("/{id}") public void delete(@PathVariable Integer id){s.eliminar(id);} }
